import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        int[] a = {2, 2, 5, 5, 5, 9};
        int write = 1;
        for (int read = 1; read < a.length; read++) {
            if (a[read] != a[write - 1]) {
                a[write++] = a[read];
            }
        }
        System.out.println(write);
        System.out.println(Arrays.toString(Arrays.copyOf(a, write)));
    }
}
